import React from 'react';
import { useAuth } from '../context/AuthContext';
import { useNavigate } from 'react-router-dom';

const Dashboard = () => {
  const { user, logout } = useAuth();
  const navigate = useNavigate();

  const handleLogout = () => {
    logout();
    navigate('/login');
  };

  const getRoleDisplay = (role) => {
    return role ? role.charAt(0).toUpperCase() + role.slice(1).toLowerCase() : 'User';
  };

  if (!user) {
    navigate('/login');
    return null;
  }

  return (
    <div className="container">
      <div className="dashboard">
        <div className="dashboard-header">
          <div className="user-info">
            <div className="user-name">👋 Welcome, {user.fullName || user.username}!</div>
            <div className="user-role">{getRoleDisplay(user.role)}</div>
          </div>
          <button className="btn btn-secondary" onClick={handleLogout}>
            🚪 Logout
          </button>
        </div>

        <div className="welcome-message">
          <h2>🎬 Welcome to Your Movie Booking Dashboard</h2>
          <p>Manage your movie bookings and explore the latest films!</p>
        </div>

        <div className="stats-grid">
          <div className="stat-card">
            <div className="stat-number">🎥 {Math.floor(Math.random() * 50) + 10}</div>
            <div className="stat-label">Movies Available</div>
          </div>
          <div className="stat-card">
            <div className="stat-number">🎫 {Math.floor(Math.random() * 5) + 1}</div>
            <div className="stat-label">Your Bookings</div>
          </div>
          <div className="stat-card">
            <div className="stat-number">⭐ {user.role === 'ADMIN' ? 'Admin' : 'Premium'}</div>
            <div className="stat-label">Account Status</div>
          </div>
          <div className="stat-card">
            <div className="stat-number">📅 {new Date().toLocaleDateString()}</div>
            <div className="stat-label">Last Login</div>
          </div>
        </div>

        <div style={{ marginTop: '2rem' }}>
          <h3>🎯 Quick Actions</h3>
          <div style={{ display: 'flex', gap: '1rem', marginTop: '1rem' }}>
            <button 
              className="btn btn-primary"
              onClick={() => navigate('/movies')}
              style={{ flex: 1 }}
            >
              🎥 Browse Movies
            </button>
            {user.role === 'ADMIN' && (
              <button 
                className="btn btn-success"
                onClick={() => navigate('/admin')}
                style={{ flex: 1 }}
              >
                ⚙️ Admin Panel
              </button>
            )}
          </div>
        </div>

        <div style={{ marginTop: '2rem', background: '#f8f9fa', padding: '1rem', borderRadius: '10px' }}>
          <h3>👤 Account Information</h3>
          <div style={{ display: 'grid', gap: '0.5rem', marginTop: '1rem' }}>
            <p><strong>User ID:</strong> {user.userId}</p>
            <p><strong>Username:</strong> {user.username}</p>
            <p><strong>Email:</strong> {user.email}</p>
            <p><strong>Full Name:</strong> {user.fullName || 'Not provided'}</p>
            <p><strong>Role:</strong> {getRoleDisplay(user.role)}</p>
            <p><strong>Account Status:</strong> <span style={{ color: '#28a745' }}>✅ Active</span></p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;
